/* the sale as lib/shop-sale.ts builds it, from the saved campaign (the Black Friday page stands in for both sale pages) */
const SHOP_SALE = (() => {
  const c = SHOP.campaign;
  if (!c || c.over) return null;
  const at = (p) => ({ ...p, from: Date.parse(p.from), to: Date.parse(p.to) });
  const bf = c.phases.map(at).find((p) => p.id === 'black-friday');
  if (!bf) return null;
  const now = c.phases.map(at).find((p) => p.id === c.phase) || null;
  const day = (t) => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Toronto', month: 'short', day: 'numeric' }).format(t).replaceAll('.', '');
  return { now: now ? { label: now.label, to: now.to } : null, blackFriday: { label: bf.label, from: bf.from, to: bf.to, days: `${day(bf.from)} to ${day(bf.to)}` },
    headline: SHOP.headline, link: 'black-friday-sale.html', cta: c.phase === 'vip' ? 'Shop the VIP Sale' : `See ${(now || bf).label} offers` };
})();
/* the product page: ?p=<slug>, else the first product */
const SHOP_CURRENT = (() => {
  const slug = new URLSearchParams(window.location.search).get('p');
  return SHOP.products.find((p) => p.slug === slug) || SHOP.products[0];
})();
const SHOP_CRUMBS = SHOP_CURRENT ? [...(SHOP_CURRENT.brand ? [[SHOP_CURRENT.brand, `shop.html?brand=${encodeURIComponent(SHOP_CURRENT.brand)}#products`]] : []), SHOP_CURRENT.name] : ['Product'];
/*
 * Which products show around a product (its page) and in the shop's routine, worked out from the store's own data
 * only. No server code: the prototype (shop-product.html) runs the same functions.
 */
const shared = (a, b) => a.filter((x) => b.includes(x)).length;
const byName = (a, b) => a.name.localeCompare(b.name, "en", { sensitivity: "base" });
/** "Complete the routine": up to four products of the same product line (else the same brand and category), in stock. */
function sameLine(product, all, count = 4) {
    const pool = all.filter((p) => p.id !== product.id && p.inStock && p.image);
    const line = product.line ? pool.filter((p) => p.line === product.line) : [];
    const near = line.length ? line : pool.filter((p) => p.brand === product.brand && shared(p.categories, product.categories) > 0);
    return near.sort((a, b) => shared(b.concerns, product.concerns) - shared(a.concerns, product.concerns) || byName(a, b)).slice(0, count);
}
/** "You may also like": up to four products that share its concerns and category, leaving out `skip` (the routine row). */
function alsoLike(product, all, skip = [], count = 4) {
    const out = new Set([product.id, ...skip.map((p) => p.id)]);
    const score = (p) => shared(p.concerns, product.concerns) * 2 + shared(p.categories, product.categories) + shared(p.ingredients, product.ingredients) * 0.5 + (p.brand === product.brand ? 0.5 : 0);
    return all
        .filter((p) => !out.has(p.id) && p.inStock && p.image)
        .map((p) => [p, score(p)])
        .filter(([, n]) => n > 0)
        .sort((a, b) => b[1] - a[1] || byName(a[0], b[0]))
        .slice(0, count)
        .map(([p]) => p);
}
const isType = (p, t) => p.productTypes.includes(t);
const pick = (all, used, tests) => {
    for (const test of tests) {
        const found = all.filter((p) => p.inStock && p.image && !used.has(p.id) && !p.areas.includes("Intimate") && test(p)).sort((a, b) => b.regular - a.regular)[0];
        if (found) {
            used.add(found.id);
            return found;
        }
    }
    return undefined;
};
/**
 * Two example routines of three steps (cleanse, treat, moisturise), picked from the store's product types,
 * ingredients and names: a morning one around vitamin C, an evening one around retinol and a night cream.
 * A step the store has nothing for is left out.
 */
function routines(all) {
    const make = (tests) => {
        const used = new Set();
        return tests.flatMap(([step, t]) => {
            const p = pick(all, used, t);
            return p ? [{ step, p }] : [];
        });
    };
    const cleanser = (p) => isType(p, "Cleansers and Toners");
    const serum = (p) => isType(p, "Concentrates and Serums");
    const cream = (p) => isType(p, "Creams and Gels") && p.areas.includes("Face") && !p.areas.includes("Eyes");
    return [
        {
            id: "morning",
            label: "Morning",
            steps: make([
                ["Cleanse", [(p) => cleanser(p) && /foam|mousse|gel/i.test(p.name), cleanser]],
                ["Treat", [(p) => serum(p) && p.ingredients.includes("Vitamin C"), serum]],
                ["Moisturise", [(p) => cream(p) && p.concerns.includes("Dry/Dehydrated Skin") && !/night/i.test(p.name), (p) => cream(p) && !/night/i.test(p.name)]],
            ]),
        },
        {
            id: "evening",
            label: "Evening",
            steps: make([
                ["Cleanse", [(p) => cleanser(p) && /micellar|cleanser/i.test(p.name), cleanser]],
                ["Treat", [(p) => serum(p) && p.ingredients.includes("Retinol"), (p) => p.ingredients.includes("Retinol")]],
                ["Moisturise", [(p) => cream(p) && /night/i.test(p.name), cream]],
            ]),
        },
    ].filter((r) => r.steps.length > 1);
}

const cad = (cents) => `$${(cents / 100).toFixed(2)}`;
