          <img src={optimized(PHOTO, 1080)} srcSet={optimizedSrcSet(PHOTO, [640, 828, 1080]) || undefined} sizes="(min-width: 1024px) 42vw, 100vw" alt="" loading="lazy" className="absolute inset-0 h-full w-full object-cover object-[50%_30%]"/>
